\label{thm:A}
The restriction of the coproduct
$\Delta:\mathrm{Y}_{m|n}\rightarrow \mathrm{Y}_{m|n} \otimes \mathrm{Y}_{m|n}$ 
induces a homomorphism
\begin{equation*}
\Delta:\mathrm{Y}_{m|n}(\sigma)\rightarrow \mathrm{Y}_{m|n}(\sigma^\prime) \otimes \mathrm{Y}_{m|n}(\sigma^{\prime\prime}).
\end{equation*}
Moreover, this homomorphism factors through the corresponding quotients to yield a homomorphism of finite $W$-superalgebras 
\begin{equation*}
\Delta_{\ell^\prime,\ell^{\prime\prime}} : W(\pi) \rightarrow W(\pi^\prime)\otimes W(\pi^{\prime\prime}).
\end{equation*}

\label{thm:C}
We have the following.
\begin{enumerate} 
    \item When $\pi$ is a standard pyramid (i.e. the parity sequence $\mathfrak{s}$ corresponding to $\pi$ is standard), a criterion for the irreducible $W(\pi)$-modules $\mathcal L(\mathbf{A})$ to be finite dimensional is obtained.
    \item For $\mathbf{A}\in \mathrm{Row}(\pi)$, an explicit character formula \eqref{eq:ch-Verma} for $\mathcal M(\mathbf{A})$ is obtained.
\end{enumerate}

\label{def:sY}
The \textit{shifted super Yangian} $\mathrm{Y}_{m|n}(\sigma)$ is the unital $\mathbb{Z}_2$-graded algebra generated by the elements 
\begin{align}
    &\big\{D_i^{(r)},D_i^{\prime(r)} \mid 1\leqslant i\leqslant m+n,r>0\big\},\label{eq:D-gen}\\
    &\big\{E_j^{(r)}\mid 1\leqslant j< m+n,r>s_{j,j+1}\big\},\\
    &\big\{F_j^{(r)}\mid 1\leqslant j< m+n,r>s_{j+1,j}\big\},\label{eq:F-gen}
\end{align}
where $D_i^{(r)}$, $D_i^{\prime(r)}$ are even elements while 
\begin{equation}\label{z2par}
|E_j^{(r)}|=|F_j^{(r)}|=|{j}|+|{j+1}|,
\end{equation}
and subject to the following relations:
\begin{align}
\sum_{t=0}^{r}D_{i}^{(r-t)}D_{j}^{\prime (t)}&=\sum_{t=0}^{r}D_{j}^{\prime (r-t)}D_{i}^{(t)}=\delta_{r0}\delta_{ij},\,\label{dr1}\\
\big[D_{i}^{(r)},D_{j}^{(s)}\big]&=0, \label{dr2} \\
 [D_{i}^{(r)}, E_{j}^{(s)}]
        &=\mathfrak{s}_i(\delta_{i,j}-\delta_{i,j+1})\sum_{t=0}^{r-1} D_{i}^{(t)} E_{j}^{(r+s-1-t)}
        ,\label{dr3}\\
 [D_{i}^{(r)}, F_{j}^{(s)}]
        &=\mathfrak{s}_i(\delta_{i,j+1}-\delta_{i,j})\sum_{t=0}^{r-1} F_{j}^{(r+s-1-t)}D_{i}^{(t)},  \label{dr4}  \\
 [E_{i}^{(r)} , F_{j}^{(s)}]
        &=-\delta_{i,j}\mathfrak{s}_{i+1}
        \sum_{t=0}^{r+s-1} D_{i}^{\prime (r+s-1-t)} D_{i+1}^{(t)},    \label{dr5} \\
 [E_{i}^{(r)} , E_{i}^{(s)}]
        &=\mathfrak{s}_{i+1}
          \Big( \sum_{t=s_{i,i+1}+1}^{s-1} E_{i}^{(t)} E_{i}^{(r+s-1-t)} 
          -\sum_{t=s_{i,i+1}+1}^{r-1} E_{i}^{(t)} E_{i}^{(r+s-1-t)}  \Big),    \label{dr6} \\
 [F_{i}^{(r)} , F_{i}^{(s)}]
         & =\mathfrak{s}_{i+1} 
          \Big( \sum_{t=s_{i+1,i}+1}^{r-1} F_{i}^{(r+s-1-t)} F_{i}^{(t)} 
          -\sum_{t=s_{i+1,i}+1}^{s-1} F_{i}^{(r+s-1-t)} F_{i}^{(t)}  \Big),   \label{dr7} \\
 [E_{i}^{(r+1)}, E_{i+1}^{(s)}]&-[E_{i}^{(r)}, E_{i+1}^{(s+1)}]
=\mathfrak{s}_{i+1} E_{i}^{(r)}E_{i+1}^{(s)}\,, \label{dr8}      \\[2mm]
[F_{i+1}^{(s)}, F_{i}^{(r+1)}]&-[F_{i+1}^{(s+1)}, F_{i}^{(r)}]
=\mathfrak{s}_{i+1} F_{i+1}^{(s)}F_{i}^{(r)}\,, \label{dr9}\\[2mm]
[E_{i}^{(r)}, E_{j}^{(s)}] &= [F_{i}^{(r)}, F_{j}^{(s)}]=0
\qquad\qquad\text{\;\;if\;\; $|i-j|>1$}, \label{dr10} \\[2mm]
\big[E_{i}^{(r)},[E_{i}^{(s)}&,E_{j}^{(t)}]\big]+
\big[E_{i}^{(s)},[E_{i}^{(r)},E_{j}^{(t)}]\big]=0 \quad \text{if}\,\,\, |i-j|=1, \label{dr11}\\[2mm]
\big[F_{i}^{(r)},[F_{i}^{(s)}&,F_{j}^{(t)}]\big]+
\big[F_{i}^{(s)},[F_{i}^{(r)},F_{j}^{(t)}]\big]=0 \quad \text{if}\,\,\, |i-j|=1, \label{dr12} \\[2mm]
\big[\,[E_{i}^{(r)},E_{i+1}^{(t)}]\,&,\,[E_{i+1}^{(t)},E_{i+2}^{(s)}]\,\big]=0 \;\;\text{if\;\;}  m+n\geqslant 4, \, |{i+1}|\neq|{i+2}|, \label{sdr1}\\[2mm]
\big[\,[F_{i}^{(r)},F_{i+1}^{(t)}]\,&,\,[F_{i+1}^{(t)},F_{i+2}^{(s)}]\,\big]=0 \;\;\text{if\;\;}  m+n\geqslant 4, \, |{i+1}|\neq|{i+2}|, \label{sdr2}
\end{align}
for all indices $i,j,r,s,t$ that make sense.

\label{prop:PBW}
The supermonomials in the elements
\begin{align*}
&\{D_i^{(r)}\mid 1\leqslant i\leqslant m+n,r>0\},\\
&\{E_{i,j}^{(r)}\mid1\leqslant i<j\leqslant m+n,r>s_{i,j}\},\\
&\{F_{j,i}^{(r)}\mid1\leqslant i<j\leqslant m+n,r>s_{j,i}\},
\end{align*}
respectively, taken in any fixed order form a basis for ${\mathrm{Y}_{m|n}^0}$, ${\mathrm{Y}_{m|n}^+(\sigma)}$, ${\mathrm{Y}_{m|n}^-(\sigma)}$, respectively. Moreover, the multiplicative map
\begin{equation}\label{eq:triangle}
{\mathrm{Y}_{m|n}^-(\sigma)}\otimes {\mathrm{Y}_{m|n}^0}\otimes {\mathrm{Y}_{m|n}^+(\sigma)} \stackrel{\sim}{\longrightarrow} {\mathrm{Y}_{m|n}(\sigma)} 
\end{equation}
is an isomorphism of superspaces.

\cite[Props. 5.13, 5.14]{Pe21}
\begin{enumerate}
\item 
The restriction of \eqref{tautran} gives rise to an anti-isomorphism $\tau: \mathrm{Y}_{m|n}(\sigma)\rightarrow \mathrm{Y}_{m|n}(\sigma^t)$ such that
\begin{equation}\label{taudef}
\tau(D_{i}^{(r)}) =
D_{i}^{(r)},\,\,\,
\tau(E_{j}^{(r)}) =
(-1)^{|j+1|(|j|+1)}F_{j}^{(r)},\,\,\,
\tau(F_{j}^{(r)}) =
(-1)^{|j|(|j+1|+1)}E_{j}^{(r)}.
\end{equation}
Moreover, for $1\leqslant i<j\leqslant m+n$, we have
\begin{equation}\label{taudef2}
\tau(E_{i,j}^{(r)})=(-1)^{|j|(|i|+1)}F_{j,i}^{(r)}, \quad \tau(F_{j,i}^{(r)})=(-1)^{|i|(|j|+1)}E_{i,j}^{(r)}.
\end{equation}
\item 
The map $\iota:\mathrm{Y}_{m|n}(\sigma) \rightarrow \mathrm{Y}_{m|n}({\vec{\sigma}})$ defined by
\begin{equation}\label{iotadef}
\iota(D_{i}^{(r)}) = \vec{D}_{i}^{(r)},\quad
\iota(E_{j}^{(r)}) = \vec{E}_{j}^{(r-s_{j,j+1}+\vec s_{j,j+1})},\quad
\iota(F_{j}^{(r)}) = \vec{F}_{j}^{(r-s_{j+1,j}+\vec s_{j+1,j})},
\end{equation}
is an isomorphism.
\end{enumerate}

\label{prop:copro}
The coproduct $\Delta:\mathrm{Y}_{m|n}\to \mathrm{Y}_{m|n}\otimes \mathrm{Y}_{m|n}$ has the following properties:
\begin{enumerate}
    \item $\Delta (D_i^{(r)})\equiv \sum_{s=0}^{r}D_i^{(s)}\otimes D_i^{(r-s)}$ modulo $\mathrm{K}_{m|n}^{>0}\otimes \mathrm{K}_{m|n}^{<0}$;
    \item $\Delta (E_i^{(r)})\equiv 1\otimes E_i^{(r)}+\sum_{s=1}^rE_i^{(s)}\otimes H_i^{(r-s)}$ modulo $\big(\mathrm{K}_{m|n}^{>0}\big)^2\otimes \mathrm{K}_{m|n}^{<0}$;
    \item $\Delta(F_i^{(r)})\equiv F_i^{(r)}\otimes 1+\sum_{s=1}^rH_i^{(r-s)}\otimes F_i^{(s)}$ modulo $\mathrm{K}_{m|n}^{>0}\otimes \big(\mathrm{K}_{m|n}^{<0}\big)^2$.
\end{enumerate}

\label{lem:copro-res}
The coproduct $\Delta:\mathrm{Y}_{m|n}\to \mathrm{Y}_{m|n}\otimes \mathrm{Y}_{m|n}$ restricts to a superalgebra homomorphism
\begin{equation}\label{eq:coproduct}
\Delta:{\mathrm{Y}_{m|n}(\sigma)}\to \mathrm{Y}_{m|n}(\sigma')\otimes \mathrm{Y}_{m|n}(\sigma'').
\end{equation}

\label{thm:pe21}
The elements
\begin{align}\label{Wdi}
&\{\mathsf{T}_{i,i;i-1}^{(r)} \, | \, 1\leqslant i\leqslant m+n, \, r> s_{i,i}\}\\ \label{Wei}
&\{\mathsf{T}_{i,i+1;i}^{(r)} \, | \, 1\leqslant i\leqslant m+n-1, \, r> s_{i,i+1}\}\\ \label{Wfi}
&\{\mathsf{T}_{i+1,i;i}^{(r)} \, | \, 1\leqslant i\leqslant m+n-1, \, r> s_{i+1,i}\}
\end{align}
in $\mathrm{U}(\mathfrak{p})$ defined by \eqref{mystery} are $\mathfrak{m}$-invariants and they generate the subalgebra $W(\pi)$. 
Moreover, there exists a unique surjective homomorphism 
\begin{equation} \label{omegadef}
\Omega: \mathrm{Y}_{m|n}(\sigma) \twoheadrightarrow W(\pi)
\end{equation}
such that 
\begin{equation}\label{omega2}
\Omega(D_i^{(r)})=\mathsf{T}_{i,i;i-1}^{(r)}, \quad \Omega(E_i^{(r)})=\mathsf{T}_{i,i+1;i}^{(r)}, \quad \Omega(F_i^{(r)})=\mathsf{T}_{i+1,i;i}^{(r)}, 
\end{equation}
where the kernel of $\Omega$ is the two-sided ideal generated by $\{D_{1}^{(r)}\,|\, r> p_1\}$.

\label{prop:PBW-truncated}
The supermonomials in the elements
\begin{align*}
&\{D_i^{(r)}\mid 1\leqslant i\leqslant m+n,0<r\leqslant p_i\},\\
&\{E_{i,j}^{(r)}\mid1\leqslant i<j\leqslant m+n,s_{i,j}<r\leqslant s_{i,j}+p_i\},\\
&\{F_{j,i}^{(r)}\mid1\leqslant i<j\leqslant m+n,s_{j,i}<r\leqslant s_{j,i}+p_i\}
\end{align*}
taken in any fixed order form a basis for $\mathrm{Y}_{m|n}^\ell(\sigma)$.

\label{prop:PBW-T-truncated}
The supermonomials in the elements 
\begin{equation*}
\{T_{i,j}^{(r)}\mid 1\leqslant i,j\leqslant m+n,s_{i,j}<r\leqslant s_{i,j}+p_{\min(i,j)}\}
\end{equation*}
taken in some fixed order form a basis for $\mathrm{Y}_{m|n}^\ell(\sigma)$.

For $1\leqslant i,j \leqslant m+n$, $r>0$,
\begin{equation}\label{coproductW}
\Delta_{\ell^\prime,\ell^{\prime\prime}}(\mathsf{T}_{i,j;0}^{(r)})=\sum_{s=0}^{r} \sum_{k=1}^{m+n} \mathsf{T}_{i,k;0}^{(s)}\otimes \mathsf{T}_{k,j;0}^{(r-s)}.
\end{equation}

\label{wasso}
Suppose $\ell=\ell^\prime+\ell^{\prime\prime}+\ell^{\prime\prime\prime}$ for some non-negative integers $\ell^\prime,\ell^{\prime\prime},\ell^{\prime\prime\prime}$ and let $\pi=\pi^\prime\otimes\pi^{\prime\prime}\otimes\pi^{\prime\prime\prime}$, where $\pi^\prime$ means the pyramid consisting of the leftmost $\ell^\prime$ columns of $\pi$,
$\pi^{\prime\prime}$ means the pyramid consisting of the middle $\ell^{\prime\prime}$ columns of $\pi$,
and $\pi^{\prime\prime\prime}$ means the pyramid consisting of the rightmost $\ell^{\prime\prime\prime}$ columns of $\pi$.
Then the following diagram commutes.
\begin{equation*}
\begin{CD}
W(\pi^\prime \otimes \pi^{\prime\prime} \otimes \pi^{\prime\prime\prime}) & @>\Delta_{\ell^\prime+\ell'',\ell'''}>> & W(\pi^\prime \otimes \pi'') \otimes W(\pi''')\\
@V\Delta_{\ell^\prime,\ell^{\prime\prime}+\ell^{\prime\prime\prime}} VV&&@VV\Delta_{\ell^\prime,\ell^{\prime\prime}} \otimes 1V\\
W(\pi^\prime) \otimes W(\pi'' \otimes \pi''') &@>1 \otimes \Delta_{\ell^{\prime\prime},\ell^{\prime\prime\prime}}>> &W(\pi^\prime) \otimes W(\pi'')
\otimes W(\pi''')
\end{CD}
\end{equation*}

\label{lem:paraiota}
Suppose that $\pi=\pi^\prime\otimes\pi^{\prime\prime}$ and $\vec{\pi}={\vec\pi}^\prime\otimes{\vec\pi}^{\prime\prime}$ are pyramids such that 
${\vec\pi}^\prime$ and ${\vec\pi}^{\prime\prime}$ have same row lengths as $\pi^\prime$ and $\pi^{\prime\prime}$, respectively. Then the following diagram commutes:
\begin{equation*}
\begin{CD}
W(\pi) & @>\iota>> & W(\vec\pi)\\
@V\Delta_{\ell^\prime,\ell^{\prime\prime}} VV&&@VV\Delta_{\ell^\prime,\ell^{\prime\prime}} V\\
W(\pi^\prime) \otimes W(\pi^{\prime\prime}) &@> \iota \otimes \iota >> &  W(\vec\pi^\prime) \otimes W(\vec\pi^{\prime\prime}),
\end{CD}
\end{equation*}
where $\ell^\prime,\ell^{\prime\prime}$ are levels of $\pi^\prime, \pi^{\prime\prime}$, respectively, with $\ell=\ell^\prime+\ell^{\prime\prime}$.

We argue by induction on $\ell$. There is nothing to prove if either $\ell^\prime=0$ or $\ell^{\prime\prime}=0$, hence the statement holds trivially in the base case $\ell=1$. Assume from now on $\ell=\ell^\prime+\ell^{\prime\prime}$ with $\ell^\prime, \ell^{\prime\prime}>0$.
In any case, at least one of $\Delta_L$ and $\Delta_R$ is defined. We explain the inductive step in the case where $\Delta_R$ is defined, where in the other case the argument is almost identical.
Note that when $\Delta_R$ is defined on $W(\pi)$, by our assumptions on the lengths of rows, we ensure that $\Delta_R$ is defined on $W(\vec\pi)$ as well.

Consider first that $\ell^{\prime\prime}=1$. By Lemma \ref{nwbaby}, $\Delta_{\ell^\prime,\ell^{\prime\prime}}=\Delta_R$ for both $W(\pi)$ and $W(\vec\pi)$. Then the commutativity of the diagram can be checked by the explicit formula of $\Delta_R$ and $\iota$ in \cite[Thm.~6.1 (1)]{Pe21} and \cite[(5.23)]{Pe21} when they evaluate on parabolic generators.

