\label{rem:parity}
Recall the observation in \cite{Pe14} (see also \cite{Ts20} for a proof) that the definition of the super Yangian $\mathrm{Y}_{m|n}$ is independent of the choice of the parity sequence $\mathfrak{s}$, up to isomorphism. A similar result holds for $\mathrm{Y}_{m|n}(\sigma)$ as follows. Let $\mu=(\mu_1,\ldots,\mu_z)$ be the minimal admissible shape of $\sigma$ and let $\mathfrak{S}_\mu$ denote the corresponding Young subgroup of $\mathfrak{S}_{m+n}$. Consider the obvious action of $\mathfrak{S}_\mu$ permuting the parity sequence $\mathfrak{s}$. Then we have 
\begin{equation}\label{row-permute}
\mathrm{Y}_{m|n}(\sigma, \mathfrak{s}) \cong \mathrm{Y}_{m|n}(\sigma,\omega\mathfrak{s}), \quad \forall\, \omega\in \mathfrak{S}_\mu,
\end{equation}
where the notation $\mathrm{Y}_{m|n}(\sigma, \mathfrak{s})$ emphasizes the choice of the parity sequence $\mathfrak{s}$.
We first establish this fact for the truncation $\mathrm{Y}_{m|n}^\ell(\sigma, \mathfrak{s})\cong \mathrm{Y}_{m|n}^\ell(\sigma,\omega\mathfrak{s})$.
Indeed, this can be easily deduced from the fact that permuting the sequence $\mathfrak{s}$ is equivalent to permuting the rows of $\pi$, and any permutation in $\mathfrak{S}_\mu$ does not change the corresponding nilpotent element \eqref{e_pi}. Since the definition of $W$-superalgebra depends only on the even nilpotent element $e$ \cite{GG02,Zha14}, we have $W(\pi)\cong W(\omega\pi)$, which further implies that 
\begin{equation}\label{row-permute-tr}
\mathrm{Y}_{m|n}^\ell(\sigma, \mathfrak{s})\cong \mathrm{Y}_{m|n}^\ell(\sigma,\omega\mathfrak{s}),  \quad \forall\, \omega\in \mathfrak{S}_\mu.
\end{equation}
Then a similar inverse limit argument as in Theorem \ref{thm:grownup} deduces \eqref{row-permute}. 
As a consequence, when necessary, one may first permute rows of $\pi^\prime$ and $\pi^{\prime\prime}$, making them $\mathfrak{s}$-compatible, and then construct the outer tensor of their modules.

Consider $\mathfrak{gl}_{2|2}$. Let $\mathfrak{s}=(1,1,-1,-1)$ be the standard one, where $(\kappa_1,\kappa_2,\kappa_3,\kappa_4)=(0,1,1,0)$. Thus ${\mathbb I}=\{1\lhd 2\lhd \overline{1} \lhd \overline{2}\}$, and 
\begin{multline*}
z_{2|2,\mathfrak{s}}(u)=\zeta_{1}(u)\zeta_2(u-1)\big(\zeta_{\overline{1}}(u-1)\zeta_{\overline{2}}(u)\big)^{-1}=\frac{(u+e_{1,1})(u-1+e_{2,2})}{(u-1-e_{3,3})(u-e_{4,4})}\\
=\frac{(u+(e_{1,1}-0))(u+(e_{2,2}-1))}{(u-(e_{3,3}+1))(u-(e_{4,4}+0))}\stackrel{\operatorname{HC}^\mathfrak{s}}{\Rightarrow}
\frac{(u+e_{1,1})(u+e_{2,2})}{(u-e_{3,3})(u-e_{4,4})}
=\frac{(u+x_1)(u+x_2)}{(u+y_1)(u+y_2)}.
\end{multline*}
On the other hand, choose $\tilde\mathfrak{s} =(-1,1,-1,1)$, where $\kappa_i=-1$ for all $1\leqslant i\leqslant 4$.
Thus ${\mathbb I}=\{\overline{1}\lhd 1\lhd \overline{2} \lhd 2\}$, and 
\begin{multline*}
z_{2|2,\tilde\mathfrak{s}}(u)=\big(\zeta_{\overline{1}}(u+1)\big)^{-1}\zeta_1(u+1)\big(\zeta_{\overline{2}}(u+1)\big)^{-1}\zeta_2(u+1)
=\frac{(u+1+e_{1,1})(u+1+e_{2,2})}{(u+1-e_{3,3})(u+1-e_{4,4})}\\
=\frac{(u+(e_{1,1}+1))(u+(e_{2,2}+1))}{(u-(e_{3,3}-1))(u-(e_{4,4}-1))}\stackrel{\operatorname{HC}^{\tilde\mathfrak{s}}}{\Rightarrow}
\frac{(u+e_{1,1})(u+e_{2,2})}{(u-e_{3,3})(u-e_{4,4})}
=\frac{(u+x_1)(u+x_2)}{(u+y_1)(u+y_2)}.
\end{multline*}

\label{prop:PBW-Verma-Y}
For any $\bm\lambda\in \mathscr P_{m|n}$, the following sets of vectors form bases for the Verma module $\mathcal M(\sigma,\bm\lambda)$:
\begin{enumerate}
    \item $\{xw_{\bm\lambda}\mid x\in \mathcal X\}$, where $\mathcal X$ denotes the collection of all supermonomials in the elements $\{F_{j,i}^{(r)}\mid 1\leqslant i<j\leqslant m+n,r>s_{j,i}\}$ taken in some fixed order;
    \item $\{yw_{\bm\lambda}\mid y\in \mathcal Y\}$, where $\mathcal Y$ denotes the collection of all supermonomials in the elements $\{T_{j,i}^{(r)}\mid 1\leqslant i<j\leqslant m+n,r>s_{j,i}\}$ taken in some fixed order.
\end{enumerate}

\label{lem:1-dim}
Let $\bm\zeta$ be an $\bm\ell$-weight such that
\[
\frac{\zeta_i(u)}{\zeta_{i+1}(u)}=\frac{u^{d_i}}{Q_i(u)}
\]
where $d_i:=s_{i,i+1}+s_{i+1,i}$ and $Q_i(u)$ is a monic polynomial in $u$ of degree $d_i$ for all $1\leqslant i<m+n$. Then the ${\mathrm{Y}_{m|n}(\sigma)}$-module $\mathcal L(\sigma,\bm\zeta)$ is 1-dimensional.

\label{prop:res-rk1}
Under the above assumption, we have the following.
\begin{enumerate}
    \item The dimension of $\mathcal L(\sigma,\bm\lambda)$ is $2^r$ with a basis given by 
    \begin{equation}\label{eq:basis-rk1}
    \{F_1^{(i_1)}\cdots F_1^{(i_k)}v_{\bm\lambda}\mid 0\leqslant k\leqslant r,s_{2,1}<i_1<\cdots<i_k\leqslant s_{2,1}+r\}.
    \end{equation}
    \item If $d>0$, then $\mathcal L(\sigma,\bm\lambda)$ is isomorphic to the restriction of the $\mathrm{Y}_{1|1}$-module $\mathcal L(\bm\lambda)$ if and only if $f(0)\ne 0$.
\end{enumerate}

(1). Recall $\mu_{\wp}$ from \eqref{eq:mu-f} which fixes $F_1^{(r)}$ for all $r>0$. Twisting the module $\mathcal L(\sigma,\bm\lambda)$ by the automorphism $\mu_\wp$ with suitable $\wp(u)$, we can assume
\begin{equation}\label{eq:form}
\lambda_1(u)=u^{-r}P(u),\qquad \lambda_2(u)=u^{-d-r}Q(u).
\end{equation}

Let $W(\pi)$ be the corresponding finite $W$-superalgebra obtained via the quotient $\Omega$. It follows from \cite[\S7]{BBG13} that there exists an irreducible $W$-module denoted by $\overline L(\substack{a_1 \cdots a_{r} \\ b_1 \cdots b_{d+r}})$. Pulling back through the quotient homomorphism $\Omega$, $\overline L(\substack{a_1 \cdots a_{r} \\ b_1 \cdots b_{d+r}})$ remains to be irreducible as a $\mathrm{Y}_{1|1}(\sigma)$-module. Moreover, it is a highest $\bm\ell$-weight module with highest $\bm\ell$-weight $\bm\lambda$. Hence it is isomorphic to $\mathcal L(\sigma,\bm\lambda)$ and the statement follows from \cite[Thm.~7.3]{BBG13}.


(2). If $f(0)\ne 0$, then $(f(u),u^d)=1$ and hence $f(u)=P(u)$. This implies $r=\deg f(u)$. It is known from \cite[Thm.~4]{Zh95} that  the $\mathrm{Y}_{1|1}$-module $\mathcal L(\bm\lambda)$ has dimension $2^r$. Thus it follows from Part (1) that $\mathcal L(\sigma,\bm\lambda)$ and the $\mathrm{Y}_{1|1}$-module $\mathcal L(\bm\lambda)$ have the same dimension. The statement follows as $\mathcal L(\sigma,\bm\lambda)$ is a sub-quotient of the restriction module $\mathcal L(\bm\lambda)$.

\label{thm:fd}
Let $\mathfrak{s}$ be the standard parity sequence. For $\bm\lambda\in\mathscr P_{m|n}$, the irreducible ${\mathrm{Y}_{m|n}(\sigma)}$-module $\mathcal L(\sigma,\bm\lambda)$ is finite dimensional if and only if there exist (necessarily unique) monic polynomials $P_i(u),Q_i(u)$ for $1\leqslant i<m+n$ such that $\deg P_m(u)=\deg Q_m(u)$, $(P_i(u),Q_i(u))=1$, $Q_j(u)$ is of degree $d_j:=s_{j,j+1}+s_{j+1,j}$, and
\begin{equation}\label{eq:fd-criterion}
\frac{\lambda_j(u)}{\lambda_{j+1}(u)}=\frac{P_j(u)}{P_{j}(u-\mathfrak{s}_j)}\times \frac{u^{d_j}}{Q_j(u)},\qquad 
\frac{\lambda_m(u)}{\lambda_{m+1}(u)}=\frac{P_m(u)}{Q_{m}(u)},
\end{equation}
for each $1\leqslant j<m+n$ and $j\ne m$.

\label{thm:W-rep-basis}
For $\bm\lambda\in \mathscr P_{m|n}$, the $W(\pi)$-module $W(\pi)\otimes_{\mathrm{Y}_{m|n}(\sigma)}\mathcal M(\sigma,\bm\lambda)$ is non-zero if and only if $u^{p_i}\lambda_i(u)\in \mathbb{C}[u]$ for all $1\leqslant i\leqslant m+n$. In that case, the following sets of vectors form bases for $W(\pi)\otimes_{\mathrm{Y}_{m|n}(\sigma)}\mathcal M(\sigma,\bm\lambda)$:
\begin{enumerate}
    \item $\{xv_+\mid x\in \mathcal X\}$, where $\mathcal X$ denotes the collection of all supermonomials in the elements $\{F_{j,i}^{(r)}\mid 1\leqslant i<j\leqslant m+n,s_{j,i}<r\leqslant s_{j,i}+p_i\}$ taken in some fixed order;
    \item $\{yv_+\mid y\in \mathcal Y\}$, where $\mathcal Y$ denotes the collection of all supermonomials in the elements $\{T_{j,i}^{(r)}\mid 1\leqslant i<j\leqslant m+n,s_{j,i}<r\leqslant s_{j,i}+p_i\}$ taken in some fixed order.
\end{enumerate}

\label{eg:1-col}
Suppose the pyramid $\pi$ consists of a single column of height $m'+n'\leqslant m+n$, where $m'$ and $n'$ denote respectively the numbers of even and odd boxes, then we have $W(\pi)=\mathrm{U}(\mathfrak{gl}_{m'|n'})$. Let $\mathbf{A}$ be a $\pi$-tableau
with entries $a_1,\cdots,a_{m'+n'}\in \mathbb C$ from top to bottom. A highest $\bm\ell$-weight vector for $W(\pi)$ of type $\mathbf{A}$ is a vector such that
\begin{enumerate}
    \item $e_{i,j}v^+=0$ for all $1\leqslant i<j\leqslant m'+n'$;
    \item $e_{i,i}v^+=\mathfrak{s}_{m+n-m'-n'+i}(a_i+\kappa_{m+n-m'-n'+i})v^+$ for all $1\leqslant i\leqslant m'+n'$.
\end{enumerate}
Thus the module $\mathcal M(\mathbf{A})$ is exactly the Verma module $\mathcal M(\alpha)$ over $\mathrm{U}(\mathfrak{gl}_{m'|n'})$ with some suitable weight $\alpha$.

\label{thm:character}
For $\mathbf{A}\in \mathrm{Row}(\pi)$ with entries $a_{i,1},\dots,a_{i,p_i}$ on the $i$-th row for each $1\leqslant i\leqslant m+n$, we have
\begin{equation}\label{eq:ch-Verma}
\begin{split}
&\mathrm{ch}\,\mathcal M(\mathbf{A})\\
=\,&\sum_{c}\prod_{i=1}^{m+n}\prod_{j=1}^{p_i}\left(y_{i,a_{i,j}-\mathfrak{s}_i(c_{i,j,i+1}+\dots+c_{i,j,m+n})}\prod_{k=i+1}^{m+n}\Big(\frac{y_{k,a_{i,j}-\mathfrak{s}_i(c_{i,j,k+1}+\dots+c_{i,j,m+n})}}{y_{k,a_{i,j}-\mathfrak{s}_i(c_{i,j,k}+\dots+c_{i,j,m+n})}}\Big)^{\mathfrak{s}_i\mathfrak{s}_k}\right),
\end{split}
\end{equation}
where the sum is over all supertuples $c=(c_{i,j,k})_{1\leqslant i<k\leqslant m+n,1\leqslant j\leqslant p_i}$.

