e\mathfrak{s}_{m+n}$.

The proof follows directly from results of \cite{Pe16} together with some simple inductive argument. We prove \eqref{4.6-2-k} in detail and omit the proof for others. Since $\pi$ is left-justified, $\sigma$ is upper triangular ($s_{j,i}=0$ for all $j\geqslant i$). This implies that the element $F_{j,i}^{(r)}\in \mathrm{Y}_{m|n}(\sigma)$ can be identified with $\mathsf{F}_{j,i}^{(r)}\in\mathrm{Y}_{m|n}$. Consequently, 
$F_{j,i}^{(r)}=\mathfrak{s}_{j-1}[F_{j-1}^{(1)}, F_{j-1,i}^{(r)}]$ for all $j-i\geqslant 2$, 
or in terms of generating series 
\begin{equation}\label{pf4.6}
F_{j,i}(u) = \mathfrak{s}_{j-1}[F_{j-1}^{(1)}, F_{j-1,i}(u)].
\end{equation}

It suffices to establish \eqref{4.6-2-k} in the special case $k=j+1$:
\begin{multline}\label{4.6-2-1}
(u-v)[F_{j}(u),F_{j,i}(v)]= \\
\mathfrak{s}_j\sum_{r\geqslant 0}(-1)^r \Big(\sum_{\substack{i<i_1<\cdots<i_r\leqslant j\\ i_{r+1}=j+1}}F_{i_{r+1},i_r}(u)F_{i_r,i_{r-1}}(u)\cdots F_{i_2,i_1}(u)\big(F_{i_1,i}(v)-F_{i_1,i}(u)\big) \Big).
\end{multline}
Indeed, applying $[F_{j+1}^{(1)}, ? ]$ to both sides of \eqref{4.6-2-1}, using the facts that $[F_{j+1}^{(1)},F_{j,i}(v)]=0$, which follows from \eqref{dr10}, and $[F_{j+1}^{(1)},F_{j+1,h}(u)]=\mathfrak{s}_{j+1} F_{j+2,h}(u)$ for all $h\leqslant j$, which follows from \eqref{pf4.6}, one deduces \eqref{4.6-2-k} for $k=j+2$. Applying $[F_{t}^{(1)}, ? ]$ successively to the results for $t=j+2,\cdots,k-1$, one obtains \eqref{4.6-2-k} in general.

We prove \eqref{4.6-2-1} by induction on $j-i$. The initial case when $j-i=1$ is exactly the result of applying the shift map $\psi_{i-1}$ to \cite[(6.21)]{Pe16}, which also implies the following identity:
\begin{equation}\label{pf4.6-2}
[F_{j}(u), F_{j-1}^{(1)}]=\mathfrak{s}_{j}\big(F_{j+1,j-1}(u) - F_j(u) F_{j-1}(u)\big).
\end{equation} 
Assume now $j-i\geqslant 2$, then
\begin{align*}
&(u-v)[F_{j}(u), F_{j,i}(v)]= (u-v) \big[ F_{j}(u), [F_{j-1}^{(1)}, F_{j-1,i}(v)] \big]\mathfrak{s}_{j-1} \\
=~~&(u-v) \big[ [F_{j}(u), F_{j-1}^{(1)}], F_{j-1,i}(v) \big]\mathfrak{s}_{j-1}  \\
\stackrel{\eqref{pf4.6-2}}{=}&(u-v) \big[ F_{j+1,j-1}(u) - F_j(u) F_{j-1}(u), F_{j-1,i}(v) \big]\mathfrak{s}_{j-1}\mathfrak{s}_{j}\\
=~~&(u-v) \big[ F_{j+1,j-1}(u), F_{j-1,i}(v) \big]\mathfrak{s}_{j-1}\mathfrak{s}_{j} -(u-v)F_j(u) \big[ F_{j-1}(u), F_{j-1,i}(v) \big]\mathfrak{s}_{j-1}\mathfrak{s}_{j} \\
=~~& \mathfrak{s}_j \sum_{a\geqslant 0}(-1)^a \Big(\sum_{\substack{i<i_1<\cdots<i_a\leqslant j-1\\ i_{a+1}=j+1}}F_{i_{a+1},i_a}(u)F_{i_a,i_{a-1}}(u)\cdots F_{i_2,i_1}(u)\big(F_{i_1,i}(v)-F_{i_1,i}(u)\big) \Big) \\
&- \mathfrak{s}_j \sum_{b\geqslant 0}(-1)^b F_{j}(u)\Big(\sum_{\substack{i<i_1<\cdots<i_b\leqslant j-1\\ i_{b+1}=j}}F_{i_{b+1},i_b}(u)F_{i_b,i_{r-1}}(u)\cdots F_{i_2,i_1}(u)\big(F_{i_1,i}(v)-F_{i_1,i}(u)\big) \Big) 
\end{align*}
Note that the last equality is due to the induction hypothesis. The two summations correspond to the cases when $i_r\neq j$ and $i_r=j$, respectively, in the RHS of \eqref{4.6-2-1}, completing the proof.

\label{lem:simple}
Suppose we are given $1\leqslant i<m+n$ and a vector $\mathfrak m$ of weight $\alpha$ in a $W(\pi)$-module $\mathfrak M$ such that
\begin{enumerate}
    \item $\alpha-d(\varepsilon_i-\varepsilon_{m+n})+\varepsilon_j-\varepsilon_i$ is not a weight of $\mathfrak M$ for any $1\leqslant j<i$ and $d\in\mathbb{Z}_{\geqslant 0}$;
    \item $u^{p_i}D_i(u)\mathfrak m\equiv (u+a_1)\cdots(u+a_{p_i})\mathfrak m \pmod{ \mathfrak M'[u]}$ for some $a_1,\dots,a_{p_i}\in \mathbb{C}$ and some subspace $\mathfrak M'$ of $\mathfrak M$, where $a_{j_1}-a_{j_2}\notin \mathbb{Z}$ for $j_1\ne j_2$.
\end{enumerate}
For $1\leqslant j\leqslant p_i$, define $\mathfrak{m}_j:=L_{i}(-a_j)\mathfrak{m}$. Then we have
\begin{align*}
&u^{p_i}D_i(u)\mathfrak{m}_j\\
\equiv~& (u+a_1)\cdots(u+a_{j-1})(u+a_j-\mathfrak{s}_i)(u+a_{j+1})\cdots (u+a_{p_i})\mathfrak{m}_j \pmod{\sum_{r=1}^{p_i}L_i^{(r)}\mathfrak{M}'[u]}.
\end{align*}
Moreover, the subspace of $\mathfrak{M}$ spanned by the vectors $\mathfrak{m}_1,\dots,\mathfrak{m}_{p_i}$ coincides with the subspace spanned by the vectors $L_i^{(1)}\mathfrak{m},\dots,L_{i}^{(p_i)}\mathfrak{m}$.

\label{lem:simple-generic}
Let $\mathbf{A}\in\mathrm{Row}(\pi)$ with entries $a_{i,1},\dots,a_{i,p_i}$ on its $i$-{th} row for each $1\leqslant i\leqslant m+n$, where $a_{i_1,j_1}-a_{i_2,j_2}\notin \mathbb{Z}$ for all $1\leqslant i_1,i_2\leqslant m+n$ and $1\leqslant j_1,j_2\leqslant p_i$ provided $(i_1,j_1)\ne (i_2,j_2)$. Then we have the following.
\begin{enumerate}
    \item The Verma module $\mathcal M(\mathbf{A})$ is irreducible.
    \item Let $\mathbf{A}_1,\dots,\mathbf{A}_\ell$ be the columns of any representative of the row-symmetrized $\pi$-tableau $\mathbf{A}\in \mathrm{Row}(\pi)$, so that $\mathbf{A}\sim_{\mathrm{row}}\mathbf{A}_1\otimes \mathbf{A}_2\otimes \cdots\otimes \mathbf{A}_{\ell}$. Then
\[
\mathcal M(\mathbf{A})\cong \mathcal M(\mathbf{A}_1)\boxtimes\cdots \boxtimes \mathcal M(\mathbf{A}_\ell).
\]
\end{enumerate}

